/bin/bash -lc "python3 - <<'PY'
import json
from pathlib import Path
p=Path('.archon/logs/iter-029/prover.jsonl')
for lineno,line in enumerate(p.read_text().splitlines(),1):
    try:
        obj=json.loads(line)
    except Exception as e:
        print('bad', lineno, e)
        continue
    ev=obj.get('event') or obj.get('type')
    if ev in {'session_start','turn.completed'}:
        print(lineno, ev, {k:obj.get(k) for k in ('ts','model','runner','role','usage') if k in obj})
    item=obj.get('item') or {}
    typ=item.get('type')
    if typ == 'command_execution' and item.get('status')=='completed':
        cmd=item.get('command','')
        out=item.get('aggregated_output','')
        if 'lake env lean' in cmd or 'lake build' in cmd or 'rg -n \"sorry' in cmd or 'git status' in cmd:
            print('\\nLINE',lineno,'CMD',cmd)
            print('EXIT',item.get('exit_code'))
            print(out[:1600].replace('\\n','\\n'))
    if typ == 'file_change':
        print('\\nLINE', lineno, 'FILE_CHANGE', item.get('changes'))
    if typ == 'agent_message' and item.get('text','').startswith('Implemented and verified'):
        print('\\nLINE', lineno, 'FINAL_MSG')
        print(item.get('text')[:2000])
PY"

